func TestConcurrentGeneration(t *testing.T) {
	const count = 1000
	results := make(chan string, count)
	var workers sync.WaitGroup
	for range 10 {
		workers.Go(func() {
			for range count / 10 {
				results <- New()
			}
		})
	}
	workers.Wait()
	close(results)
	seen := make(map[string]bool, count)
	for id := range results {
		if !Valid(id) || seen[id] {
			t.Fatalf("invalid or duplicate concurrent ID: %s", id)
		}
		seen[id] = true
	}
}

