			}
			if err := json.MarshalWrite(w, row); err != nil {
				t.Error(err)
			}
			return
		}
		w.WriteHeader(http.StatusNotFound)
		io.WriteString(w, `{"code":"NotFound","message":"missing exact resource"}`)
	}))
	t.Cleanup(server.Close)
	listener, ok := server.Listener.Addr().(*net.TCPAddr)
	if !ok || !listener.IP.IsLoopback() || listener.Port == 0 {
		t.Fatal("binding fixture requires literal loopback listener")
	}
	transport := http.DefaultTransport.(*http.Transport).Clone()
	original := http.DefaultTransport
	transport.Proxy = func(request *http.Request) (*url.URL, error) {
		if request.URL == nil || request.URL.Scheme != "https" || request.URL.User != nil || request.URL.Opaque != "" || request.Response != nil || request.Method == http.MethodConnect {
			return nil, fmt.Errorf("fixture refuses noninitial HTTPS request")
		}
		return nil, nil
	}
	transport.DialContext = func(context.Context, string, string) (net.Conn, error) {
		return nil, fmt.Errorf("fixture refuses plaintext dialing")
	}
	transport.DialTLSContext = func(ctx context.Context, network, _ string) (net.Conn, error) {
		if network != "tcp" && network != "tcp4" && network != "tcp6" {
			return nil, fmt.Errorf("fixture refuses network %q", network)
		}
		return (&tls.Dialer{Config: server.Client().Transport.(*http.Transport).TLSClientConfig}).DialContext(ctx, "tcp", listener.String())
	}
	http.DefaultTransport = transport
	t.Cleanup(func() { http.DefaultTransport = original; transport.CloseIdleConnections() })
	key, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		t.Fatal(err)
	}
	provider := common.NewRawConfigurationProvider(s.authority.TenancyID, "ocid1.user.oc1..test", region, "test", string(pem.EncodeToMemory(&pem.Block{Type: "RSA PRIVATE KEY", Bytes: x509.MarshalPKCS1PrivateKey(key)})), nil)
	s.factory, err = ociclient.New(provider, ociclient.Options{Region: region, Retry: ociclient.RetryOptions{MaxAttempts: 1}})
	if err != nil {
		t.Fatal(err)
	}
	return s
}

func (s *bindingScenario) publish() {
	s.t.Helper()
	intentWire, err := json.Marshal(s.intent, json.Deterministic(true))
	if err != nil {
		s.t.Fatal(err)
	}
	s.grant.Regions = []jsontext.Value{intentWire}
	payload, err := trust.EncodePayload(s.grant)
	if err != nil {
		s.t.Fatal(err)
	}
	now := time.Now().UTC().Truncate(time.Second)
	envelope, err := trust.Sign(payload, s.authority.Scope, now.Add(-time.Minute), now.Add(time.Hour), s.root)
	if err != nil {
		s.t.Fatal(err)
	}
	s.wire, err = trust.EncodeEnvelope(envelope)
	if err != nil {
		s.t.Fatal(err)
	}
	s.activeWire = append([]byte(nil), s.wire...)
	s.authority.GrantSHA256 = digest(s.wire)
	s.record.GrantSHA256 = s.authority.GrantSHA256
	var canonical map[string]any
	if err := json.Unmarshal(intentWire, &canonical); err != nil {
		s.t.Fatal(err)
	}
	canonicalWire, err := json.Marshal(canonical, json.Deterministic(true))
	if err != nil {
		s.t.Fatal(err)
	}
	s.record.IntentDigest = digest(canonicalWire)
	for key, proof := range s.record.ResourceProvenance {
		if proof.Generation == s.record.Generation {
			proof.GrantSHA256 = s.record.GrantSHA256
			proof.Create.IntentDigest = s.record.IntentDigest
			s.record.ResourceProvenance[key] = proof
		}
	}
}

const recordLimit = 128 << 10

// Authority contains the exact grant and protected home storage identity from
// the caller's currently verified bootstrap anchor. It conveys no resource IDs.
type Authority struct {
	Scope          trust.Scope
	Roots          trust.Keyring
	Policy         trust.Policy
	GrantSHA256    string
	Generation     uint64
	InstallationID string
	TenancyID      string
	Namespace      string
	Bucket         string
	Prefix         string
	Cell           string
	Keys           []string
}

// VerifiedBindings has no public constructor from observed IDs or maps.
type VerifiedBindings struct {
	factory              *ociclient.Factory
	authority            Authority
	wire                 []byte
	expires              time.Time
	ids                  map[string]string
	capacityLedger       *capacityledger.Ledger
	capacityCompartments []string
	capacityCurrency     string
	capacityChildren     jsontext.Value
	observedAt           time.Time
}

func (v VerifiedBindings) GrantSHA256() string  { return v.authority.GrantSHA256 }
func (v VerifiedBindings) Generation() uint64   { return v.authority.Generation }
func (v VerifiedBindings) Cell() string         { return v.authority.Cell }
func (v VerifiedBindings) ExpiresAt() time.Time { return v.expires }

// ForCell independently verifies another approved cell under the same exact
// root grant. Query narrowing belongs to the selected cell, not the root scope.
func (v VerifiedBindings) ForCell(ctx context.Context, cell string) (VerifiedBindings, error) {
	if v.factory == nil {
		return VerifiedBindings{}, errors.New("foundation bindings are unverified")
	}
	authority := v.authority
	authority.Cell, authority.Keys = cell, nil
	return Verify(ctx, v.factory, authority, v.wire)
}

// Resolve accepts only the verified cell's finite logical roles.
func (v VerifiedBindings) Resolve(reference string) (string, error) {
	cell, key, err := Parse(reference)
	if err != nil || v.factory == nil || !time.Now().Before(v.expires) || cell != v.authority.Cell || v.ids[key] == "" {
		return "", errors.New("foundation reference has no current independently verified binding")
	}
	return v.ids[key], nil
}

// Revalidate repeats authentication, durable record reads and all OCI Get calls.
func (v VerifiedBindings) Revalidate(ctx context.Context) error {
	if v.factory == nil {
		return errors.New("foundation bindings are unverified")
	}
	current, err := Verify(ctx, v.factory, v.authority, v.wire)
	if err != nil {
		return err
	}
	if !maps.Equal(v.ids, current.ids) {
		return errors.New("foundation bindings changed after verification")
	}
	return nil
}

func Verify(ctx context.Context, factory *ociclient.Factory, authority Authority, grantWire []byte) (VerifiedBindings, error) {
	observedAt := time.Now()
	if factory == nil || !catalog.IsCell(authority.Cell) || !canonicalDigest(authority.GrantSHA256) || authority.Generation == 0 ||
		!entityid.Valid(authority.InstallationID) || !resourceID(authority.TenancyID, "tenancy", "") ||
		authority.Namespace == "" || authority.Bucket == "" || authority.Prefix == "" || strings.ContainsAny(authority.Prefix, "\\\r\n\x00") || strings.ContainsAny(authority.Namespace+authority.Bucket, "/\\\r\n\x00") ||
		authority.Scope.Domain != "terrascale.foundation.scope" || authority.Scope.Cell != "GRU" || authority.Scope.Role != "foundation" {
		return VerifiedBindings{}, errors.New("foundation binding authority is incomplete or outside its root scope")
	}
	tenancy, err := factory.Provider().TenancyOCID()
	if err != nil || tenancy != authority.TenancyID {
		return VerifiedBindings{}, errors.New("foundation binding tenancy differs from authenticated OCI identity")
	}
	if digest(grantWire) != authority.GrantSHA256 {
		return VerifiedBindings{}, errors.New("foundation grant differs from root-pinned exact wire")
	}
	envelope, err := trust.DecodeEnvelope(grantWire)
	if err != nil {
		return VerifiedBindings{}, err
	}
	payload, err := trust.VerifyCurrent(envelope, authority.Scope, authority.Roots, time.Now(), authority.Policy)
	if err != nil {
		return VerifiedBindings{}, err
	}
	if err := verifyCurrentGrant(ctx, factory, authority, grantWire); err != nil {
		return VerifiedBindings{}, err
	}
	var approved grant
	if err := json.Unmarshal(payload, &approved, json.RejectUnknownMembers(true)); err != nil {
		return VerifiedBindings{}, fmt.Errorf("foundation grant schema: %w", err)
	}
	if approved.SchemaVersion != 2 || approved.Generation != authority.Generation || approved.InstallationID != authority.InstallationID || approved.TenancyID != tenancy ||
		!resourceID(approved.ParentCompartmentID, "compartment", "") || !resourceID(approved.SharedCompartmentID, "compartment", "") ||
		approved.MonthlyLimitMinor <= 0 || approved.Currency != "USD" && approved.Currency != "BRL" || approved.CleanupOwner == "" || len(approved.CleanupOwner) > 128 ||
		len(approved.Regions) == 0 || len(approved.Regions) > catalog.Len {
		return VerifiedBindings{}, errors.New("foundation grant lacks current schema-2 scope or spend authority")
	}
	var selected intent
	var selectedDigest string
	seen := map[string]bool{}
	for _, raw := range approved.Regions {
		var region intent
		if err := json.Unmarshal(raw, &region, json.RejectUnknownMembers(true)); err != nil {
			return VerifiedBindings{}, fmt.Errorf("foundation region intent schema: %w", err)
		}
		cell, _ := region.Plan["cell"].(string)
		if !catalog.IsCell(cell) || seen[cell] || region.Generation != approved.Generation || region.Plan["region"] != catalog.OCIRegion(cell) ||
			region.Plan["tenancy_id"] != tenancy || region.Plan["parent_compartment_id"] != approved.ParentCompartmentID || region.Plan["shared_compartment_id"] != approved.SharedCompartmentID {
			return VerifiedBindings{}, errors.New("foundation region intent differs from signed scope or repeats a cell")
		}
		if _, ok := region.Plan["resource_ids"].(map[string]any); !ok {
			return VerifiedBindings{}, errors.New("foundation region intent lacks resource roles")
		}
		seen[cell] = true
		if cell == authority.Cell {
			selected = region
			wire, err := json.Marshal(region, json.Deterministic(true))
			if err != nil {
				return VerifiedBindings{}, err
			}
			// Decode optional signed documents before canonicalizing their maps.
			var canonical map[string]any
			if err := json.Unmarshal(wire, &canonical); err != nil {
				return VerifiedBindings{}, err
			}
			wire, err = json.Marshal(canonical, json.Deterministic(true))
			if err != nil {
				return VerifiedBindings{}, err
			}
			selectedDigest = digest(wire)
		}
	}
	if !seen[authority.Cell] {
		return VerifiedBindings{}, errors.New("foundation cell is outside the signed grant")
	}
	requested := map[string]bool{}
	var signed map[string]any
	if err := json.Unmarshal(payload, &signed); err != nil {
		return VerifiedBindings{}, err
	}
	if err := collectReferences(signed, authority.Cell, requested); err != nil {
		return VerifiedBindings{}, err
	}
	if len(approved.InfrastructureSpend) != 0 && string(approved.InfrastructureSpend) != "null" {
		pins := selected.Plan["resource_ids"].(map[string]any)
		for _, key := range []string{"control_compartment", "network_compartment", "workload_compartment"} {
			if pins[key] == nil || pins[key] == "" {
				requested[key] = true
			}
		}
	}
	if len(selected.BootstrapMaterial) != 0 && string(selected.BootstrapMaterial) != "null" {
		pins := selected.Plan["resource_ids"].(map[string]any)
		for _, key := range []string{"control_compartment", "vault", "key"} {
			if pins[key] == nil || pins[key] == "" {
				requested[key] = true
			}
		}
	}
	if len(authority.Keys) != 0 {
		narrowed := map[string]bool{}
		for _, key := range authority.Keys {
			if !requested[key] || narrowed[key] {
				return VerifiedBindings{}, errors.New("requested foundation roles are outside the signed reference set or repeated")
			}
			narrowed[key] = true
		}
		requested = narrowed
	}
	if len(requested) == 0 {
		return VerifiedBindings{}, errors.New("signed grant contains no logical references for this cell")
	}
	current, err := loadRecord(ctx, factory, authority)
	if err != nil {
		return VerifiedBindings{}, err
	}
	if err := validateRecord(current, approved, authority, selectedDigest, selected.Plan, requested); err != nil {
		return VerifiedBindings{}, err
	}
	var financial *capacityledger.Ledger
	if current.CapacityLedger != nil {
		if err := current.CapacityLedger.Validate(); err != nil {
			return VerifiedBindings{}, fmt.Errorf("protected capacity ledger: %w", err)
		}
		financial = new(current.CapacityLedger.Clone())
	}
	compartments := []string{approved.ParentCompartmentID, approved.SharedCompartmentID}
	for key, id := range current.ResourceIDs {
		if strings.HasSuffix(key, "_compartment") {
			compartments = append(compartments, id)
		}
	}
	slices.Sort(compartments)
	compartments = slices.Compact(compartments)
	needed := dependencyClosure(requested)
	current.ResourceIDs = maps.Clone(current.ResourceIDs)
	maps.DeleteFunc(current.ResourceIDs, func(key, _ string) bool { return !needed[key] })
	if err := observe(ctx, factory, selected.Plan, current); err != nil {
		return VerifiedBindings{}, err
	}
	authority.Keys = slices.Clone(authority.Keys)
	authority.Roots = maps.Clone(authority.Roots)
	for key, public := range authority.Roots {
		authority.Roots[key] = ed25519.PublicKey(bytes.Clone(public))
	}
	maps.DeleteFunc(current.ResourceIDs, func(key, _ string) bool { return !requested[key] })
	expires := envelope.ExpiresAt
	if current.Stage == "foundation" && current.ExpiresAt.Before(expires) {
		expires = current.ExpiresAt
	}
	return VerifiedBindings{factory: factory, authority: authority, wire: bytes.Clone(grantWire), expires: expires, ids: current.ResourceIDs,
		capacityLedger: financial, capacityCompartments: compartments, capacityCurrency: approved.Currency,
		capacityChildren: bytes.Clone(current.PoolChildren), observedAt: observedAt}, nil
}

func verifyCurrentGrant(ctx context.Context, factory *ociclient.Factory, authority Authority, expected []byte) error {
	home, err := factory.ForRegion(catalog.OCIRegion("GRU"))
	if err != nil {
		return err
	}
	objects, err := home.ObjectStorage()
	if err != nil {
		return err
	}
	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()
	name := strings.TrimSuffix(authority.Prefix, "/") + "/foundation-scope-v1.json"
	response, err := objects.GetObject(ociclient.RequestContext(ctx), objectstorage.GetObjectRequest{NamespaceName: new(authority.Namespace), BucketName: new(authority.Bucket), ObjectName: new(name)})
	if err != nil {
		return fmt.Errorf("read current protected foundation grant: %w", err)
	}
	if response.Content == nil {
		return errors.New("current foundation grant has no content")
	}
	defer response.Content.Close()
	wire, err := io.ReadAll(io.LimitReader(response.Content, trust.MaxEnvelopeBytes+1))
	if err != nil || len(wire) > trust.MaxEnvelopeBytes || !bytes.Equal(wire, expected) {
		return errors.New("active foundation grant differs from exact root-pinned wire")
	}
	return nil
}

func loadRecord(ctx context.Context, factory *ociclient.Factory, authority Authority) (record, error) {
	home, err := factory.ForRegion(catalog.OCIRegion("GRU"))
	if err != nil {
		return record{}, err
	}
	objects, err := home.ObjectStorage()
	if err != nil {
		return record{}, err
	}
	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()
	response, err := objects.GetObject(ociclient.RequestContext(ctx), objectstorage.GetObjectRequest{
		NamespaceName: new(authority.Namespace), BucketName: new(authority.Bucket), ObjectName: new("orchestrator/regions/v1/" + authority.Cell + ".json")})
	if err != nil {
		return record{}, fmt.Errorf("read protected foundation record: %w", err)
	}
	if response.Content == nil {
		return record{}, errors.New("foundation record has no content")
	}
	defer response.Content.Close()
	if response.ETag == nil || *response.ETag == "" {
		return record{}, errors.New("foundation record has no conditional-write ETag")
	}
	wire, err := io.ReadAll(io.LimitReader(response.Content, recordLimit+1))
	if err != nil || len(wire) > recordLimit {
		return record{}, errors.New("foundation record is unreadable or oversized")
	}
	var current record
	if err := json.Unmarshal(wire, &current, json.RejectUnknownMembers(true)); err != nil {
		return record{}, fmt.Errorf("foundation record schema: %w", err)
	}
	return current, nil
}

func validateRecord(current record, approved grant, authority Authority, intentDigest string, plan map[string]any, requested map[string]bool) error {
	if current.SchemaVersion != 1 || current.Cell != authority.Cell || current.OCIRegion != catalog.OCIRegion(authority.Cell) ||
		current.TenancyID != authority.TenancyID || current.ParentCompartmentID != approved.ParentCompartmentID || current.SharedCompartmentID != approved.SharedCompartmentID ||
		current.Generation != authority.Generation || current.GrantSHA256 != authority.GrantSHA256 || current.IntentDigest != intentDigest ||
		current.OperationID != entityid.Derive("regional-foundation", authority.TenancyID, authority.Cell, fmt.Sprint(authority.Generation)) ||
		current.Epoch == 0 || current.StartedAt.IsZero() || current.UpdatedAt.Before(current.StartedAt) || current.BlockedReason != "" ||
		len(current.ResourceIDs) > 128 || len(current.ResourceProvenance) > 128 || len(current.PendingCreates) > 64 {
		return errors.New("foundation record lacks the current signed operation")
	}
	switch current.Stage {
	case "reconciled":
		if current.LeaseID != "" || !current.ExpiresAt.IsZero() || current.CompletedAt.Before(current.StartedAt) || current.CompletedAt.After(current.UpdatedAt) || len(current.PendingCreates) != 0 {
			return errors.New("foundation record has an invalid reconciled outcome")
		}
	case "foundation":
		if !entityid.Valid(current.LeaseID) || !current.ExpiresAt.After(time.Now()) || !current.ExpiresAt.After(current.UpdatedAt) || !current.CompletedAt.IsZero() {
			return errors.New("foundation record has no current scoped create lease")
		}
	default:
		return errors.New("foundation record is neither active nor reconciled")
	}
	needed := dependencyClosure(requested)
	pins := plan["resource_ids"].(map[string]any)
	for key := range needed {
		if _, pending := current.PendingCreates[key]; pending {
			return fmt.Errorf("foundation %s create is still pending", key)
		}
		id := current.ResourceIDs[key]
		if id == "" {
			return fmt.Errorf("foundation record lacks required %s", key)
		}
		// An exact root-signed dependency needs no new create, but never
		// becomes a resolvable logical reference without birth provenance.
		if !requested[key] && pins[key] == id {
			continue
		}
		proof, ok := current.ResourceProvenance[key]
		birth := proof.Create
		if !ok || proof.ResourceID != id || proof.Generation == 0 || proof.Generation > current.Generation || !canonicalDigest(proof.GrantSHA256) ||
			birth.OperationID != entityid.Derive("regional-foundation", authority.TenancyID, authority.Cell, fmt.Sprint(proof.Generation)) || !canonicalDigest(birth.IntentDigest) ||
			birth.Request.Key != key || !catalog.IsOCIRegion(birth.Request.Region) || !canonicalDigest(birth.Request.RequestDigest) ||
			birth.Request.RetryToken != "" && !canonicalDigest(birth.Request.RetryToken) || birth.FirstAttemptAt.IsZero() || birth.FirstAttemptAt.After(current.UpdatedAt) {
			return fmt.Errorf("foundation %s lacks persisted create provenance", key)
		}
		if proof.Generation == current.Generation && (proof.GrantSHA256 != current.GrantSHA256 || birth.IntentDigest != current.IntentDigest || birth.FirstAttemptAt.Before(current.StartedAt)) {
			return fmt.Errorf("foundation %s create differs from its signed generation", key)
		}
		if !strings.HasSuffix(key, "_compartment") && birth.Request.Region != current.OCIRegion {
			return fmt.Errorf("foundation %s create belongs to another OCI region", key)
		}
	}
	return nil
}

func observe(ctx context.Context, factory *ociclient.Factory, plan map[string]any, current record) error {
	regional, err := factory.ForRegion(current.OCIRegion)
	if err != nil {
		return err
	}
	ids := current.ResourceIDs
	pins := plan["resource_ids"].(map[string]any)
	for key, id := range ids {
		if !referenceKey(key) && key != "vcn" {
			continue
		}
		kind, region := key, current.OCIRegion
		switch key {
		case "control_compartment", "network_compartment", "workload_compartment":
			kind, region = "compartment", ""
		case "network_security_group", "workload_network_security_group":
			kind = "networksecuritygroup"
		}
		if !resourceID(id, kind, region) || pins[key] != nil && pins[key] != "" && pins[key] != id {
			return fmt.Errorf("foundation %s differs from its signed resource role", key)
		}
	}
	iam, err := regional.Identity()
	if err != nil {
		return err
	}
	for _, key := range []string{"control_compartment", "network_compartment", "workload_compartment"} {
		if ids[key] == "" {
			continue
		}
		response, err := iam.GetCompartment(ociclient.RequestContext(ctx), identity.GetCompartmentRequest{CompartmentId: new(ids[key])})
		if err != nil {
			return fmt.Errorf("read foundation %s: %w", key, err)
		}
		if value(response.Id) != ids[key] || value(response.CompartmentId) != current.ParentCompartmentID || response.LifecycleState != identity.CompartmentLifecycleStateActive {
			return fmt.Errorf("foundation %s live parent or lifecycle differs from signed role", key)
		}
	}
	if sameID(ids, "control_compartment", "network_compartment") || sameID(ids, "control_compartment", "workload_compartment") || sameID(ids, "network_compartment", "workload_compartment") ||
		sameID(ids, "network_security_group", "workload_network_security_group") {
		return errors.New("foundation roles share an OCI resource identity")
	}
	network, err := regional.Network()
	if err != nil {
		return err
	}
	if ids["vcn"] != "" {
		vcn, err := network.GetVcn(ociclient.RequestContext(ctx), core.GetVcnRequest{VcnId: new(ids["vcn"])})
		if err != nil {
			return fmt.Errorf("read foundation VCN: %w", err)
		}
		networkCIDR, _ := plan["network_cidr"].(string)
		subnetCIDR, _ := plan["subnet_cidr"].(string)
		if _, err := netip.ParsePrefix(networkCIDR); err != nil {
			return errors.New("signed foundation lacks a network CIDR")
		}
		if _, err := netip.ParsePrefix(subnetCIDR); err != nil {
			return errors.New("signed foundation lacks a subnet CIDR")
		}
		if value(vcn.Id) != ids["vcn"] || value(vcn.CompartmentId) != ids["network_compartment"] || value(vcn.CidrBlock) != networkCIDR || vcn.LifecycleState != core.VcnLifecycleStateAvailable {
			return errors.New("foundation VCN differs from signed network role")
		}
	}
	if ids["subnet"] != "" {
		subnetCIDR, _ := plan["subnet_cidr"].(string)
		subnet, err := network.GetSubnet(ociclient.RequestContext(ctx), core.GetSubnetRequest{SubnetId: new(ids["subnet"])})
		if err != nil {
			return fmt.Errorf("read foundation subnet: %w", err)
		}
		if value(subnet.Id) != ids["subnet"] || value(subnet.CompartmentId) != ids["network_compartment"] || value(subnet.VcnId) != ids["vcn"] || value(subnet.CidrBlock) != subnetCIDR ||
			subnet.ProhibitPublicIpOnVnic == nil || !*subnet.ProhibitPublicIpOnVnic || subnet.LifecycleState != core.SubnetLifecycleStateAvailable {
			return errors.New("foundation subnet differs from signed private network role")
		}
	}
	for _, key := range []string{"network_security_group", "workload_network_security_group"} {
		if ids[key] == "" {
			continue
		}
		response, err := network.GetNetworkSecurityGroup(ociclient.RequestContext(ctx), core.GetNetworkSecurityGroupRequest{NetworkSecurityGroupId: new(ids[key])})
		if err != nil {
			return fmt.Errorf("read foundation %s: %w", key, err)
		}
		if value(response.Id) != ids[key] || value(response.CompartmentId) != ids["network_compartment"] || value(response.VcnId) != ids["vcn"] || response.LifecycleState != core.NetworkSecurityGroupLifecycleStateAvailable {
			return fmt.Errorf("foundation %s differs from signed network role", key)
		}
	}
	if ids["vault"] == "" {
		return nil
	}
	vaults, err := keymanagement.NewKmsVaultClientWithConfigurationProvider(regional.Provider())
	if err != nil {
		return err
	}
	vaults.SetRegion(current.OCIRegion)
	regional.Configure(&vaults.BaseClient, ociclient.ServiceKMS)
	vault, err := vaults.GetVault(ociclient.RequestContext(ctx), keymanagement.GetVaultRequest{VaultId: new(ids["vault"])})
	if err != nil {
		return fmt.Errorf("read foundation vault: %w", err)
	}
	if value(vault.Id) != ids["vault"] || value(vault.CompartmentId) != ids["control_compartment"] || vault.LifecycleState != keymanagement.VaultLifecycleStateActive || vault.VaultType != keymanagement.VaultVaultTypeDefault {
		return errors.New("foundation vault differs from signed control role")
	}
	if ids["key"] == "" {
		return nil
	}
	endpoint, err := url.Parse(value(vault.ManagementEndpoint))
	if err != nil || endpoint.Scheme != "https" || endpoint.User != nil || endpoint.Port() != "" || endpoint.Path != "" || endpoint.RawQuery != "" || endpoint.Fragment != "" ||
		!strings.HasSuffix(endpoint.Hostname(), ".oraclecloud.com") || !strings.Contains(endpoint.Hostname(), "."+current.OCIRegion+".") {
		return errors.New("foundation vault has an invalid regional KMS endpoint")
	}
	keys, err := keymanagement.NewKmsManagementClientWithConfigurationProvider(regional.Provider(), endpoint.String())
	if err != nil {
		return err
	}
	regional.Configure(&keys.BaseClient, ociclient.ServiceKMS)
	key, err := keys.GetKey(ociclient.RequestContext(ctx), keymanagement.GetKeyRequest{KeyId: new(ids["key"])})
	if err != nil {
		return fmt.Errorf("read foundation key: %w", err)
	}
	if value(key.Id) != ids["key"] || value(key.CompartmentId) != ids["control_compartment"] || value(key.VaultId) != ids["vault"] || key.LifecycleState != keymanagement.KeyLifecycleStateEnabled ||
		key.ProtectionMode != keymanagement.KeyProtectionModeHsm || key.KeyShape == nil || key.KeyShape.Algorithm != keymanagement.KeyShapeAlgorithmAes || key.KeyShape.Length == nil || *key.KeyShape.Length != 32 {
		return errors.New("foundation key differs from signed vault/control role")
	}
	return nil
}

func digest(wire []byte) string {
	sum := sha256.Sum256(wire)
	return hex.EncodeToString(sum[:])
}

func canonicalDigest(value string) bool {
	decoded, err := hex.DecodeString(value)
	return err == nil && len(decoded) == 32 && hex.EncodeToString(decoded) == value
}

func resourceID(id, kind, region string) bool {
	parts := strings.Split(id, ".")
	if len(parts) < 5 || len(id) > 512 || parts[0] != "ocid1" || parts[1] != kind || parts[2] != "oc1" ||
		parts[3] != region && !(region == "us-phoenix-1" && parts[3] == "phx") && !(region == "us-ashburn-1" && parts[3] == "iad") {
		return false
	}
	for _, part := range parts[4:] {
		if part == "" {
			return false
		}
		for _, character := range part {
			if (character < 'a' || character > 'z') && (character < '0' || character > '9') {
				return false
			}
		}
	}
	return true
}

func value(pointer *string) string {
	if pointer == nil {
		return ""
	}
	return *pointer
}

func sameID(ids map[string]string, left, right string) bool {
	return ids[left] != "" && ids[left] == ids[right]
}

func dependencyClosure(requested map[string]bool) map[string]bool {
	needed := maps.Clone(requested)
	for key := range requested {
		switch key {
		case "subnet", "network_security_group", "workload_network_security_group":
			needed["network_compartment"], needed["vcn"] = true, true
		case "vault":
			needed["control_compartment"] = true
		case "key":
			needed["control_compartment"], needed["vault"] = true, true
		}
	}
	return needed
}

func collectReferences(value any, cell string, requested map[string]bool) error {
	switch value := value.(type) {
	case string:
		if !strings.HasPrefix(value, "foundation:") {
			return nil
		}
		target, key, err := Parse(value)
		if err != nil {
			return err
		}
		if target == cell {
			requested[key] = true
		}
	case map[string]any:
		for _, child := range value {
			if err := collectReferences(child, cell, requested); err != nil {
				return err
			}
		}
	case []any:
		for _, child := range value {
			if err := collectReferences(child, cell, requested); err != nil {
				return err
			}
		}
	}
	return nil
}

func Reference(cell, key string) (string, error) {
	if !catalog.IsCell(cell) || !referenceKey(key) {
		return "", errors.New("foundation reference has an unsupported cell or role")
	}
	return "foundation:" + cell + ":" + key, nil
}

// Parse rejects aliases, whitespace, unknown roles and noncanonical cells.
func Parse(reference string) (cell, key string, err error) {
	value, ok := strings.CutPrefix(reference, "foundation:")
	if !ok {
		return "", "", errors.New("foundation reference has an invalid prefix")
	}
	cell, key, ok = strings.Cut(value, ":")
	canonical, err := Reference(cell, key)
	if !ok || err != nil || canonical != reference {
		return "", "", errors.New("foundation reference is not canonical")
	}
	return cell, key, nil
}

func referenceKey(key string) bool {
	switch key {
	case "control_compartment", "network_compartment", "workload_compartment", "subnet", "network_security_group", "workload_network_security_group", "vault", "key":
		return true
	}
	return false
}

var (
	entropy = ulid.Monotonic(rand.Reader, 0)
	mu      sync.Mutex
)

// New returns a cryptographically random ULID, monotonic within a millisecond.
func New() string { return NewAt(time.Now()) }

// NewAt stamps an ID with the record's time. The entropy reader is shared and
// serialized because the library's monotonic reader is not concurrency-safe.
func NewAt(at time.Time) string {
	mu.Lock()
	defer mu.Unlock()
	return ulid.MustNew(ulid.Timestamp(at), entropy).String()
}

// Parse accepts only nonzero, uppercase, 26-character Crockford ULIDs.
func Parse(value string) (ulid.ULID, error) {
	id, err := ulid.ParseStrict(value)
	if err != nil || id == (ulid.ULID{}) || id.String() != value {
		return ulid.ULID{}, errors.New("entity ID must be a canonical uppercase ULID")
	}
	return id, nil
}

func Valid(value string) bool {
	_, err := Parse(value)
	return err == nil
}

// Derive gives an idempotent operation a stable ULID. A zero timestamp marks
// derived identities as having no creation time; the 80 entropy bits bind the
// domain-separated input. New entities use New instead.
func Derive(domain string, values ...string) string {
	h := sha256.New()
	for _, value := range append([]string{domain}, values...) {
		var size [8]byte
		binary.BigEndian.PutUint64(size[:], uint64(len(value)))
		h.Write(size[:])
		h.Write([]byte(value))
	}
	return ulid.MustNew(0, bytes.NewReader(h.Sum(nil)[:10])).String()
}

func Lookup(cell string) (Entry, bool) {
	for _, entry := range entries {
		if entry.Cell == cell {
			return entry, true
		}
	}
	return Entry{}, false
}

// IsCell reports whether cell is an exact upper-case supported cell code.
func IsCell(cell string) bool {
	_, ok := Lookup(cell)
	return ok
}

// OCIRegion returns the OCI region for an exact cell code, or "" when the cell
// is not supported.
func OCIRegion(cell string) string {
	entry, _ := Lookup(cell)
	return entry.OCIRegion
}

// IsOCIRegion reports whether region is the OCI identifier of a supported cell.
func IsOCIRegion(region string) bool {
	_, ok := CellForOCIRegion(region)
	return ok
}

// CellForOCIRegion maps an exact OCI region identifier back to its cell.
func CellForOCIRegion(region string) (Entry, bool) {
	for _, entry := range entries {
		if entry.OCIRegion == region {
			return entry, true
		}
	}
	return Entry{}, false
}

func KeyID(publicKey ed25519.PublicKey) (string, error) {
	return protocol.KeyID(publicKey)
}

// EncodePayload emits deterministic JSON for a signed payload.
func EncodePayload(value any) ([]byte, error) {
	encoded, err := json.Marshal(value, json.Deterministic(true))
	if err != nil {
		return nil, fmt.Errorf("encode trust payload: %w", err)
	}
	if err := validatePayload(encoded); err != nil {
		return nil, err
	}
	return encoded, nil
}

// Sign signs a strict, bounded JSON object for the exact supplied scope.
func Sign(payload []byte, scope Scope, issuedAt, expiresAt time.Time, privateKey ed25519.PrivateKey) (Envelope, error) {
	if len(privateKey) != ed25519.PrivateKeySize {
		return Envelope{}, fmt.Errorf("%w: invalid Ed25519 private key", ErrInvalid)
	}
	if err := scope.validate(); err != nil {
		return Envelope{}, err
	}
	compact, err := compactPayload(payload)
	if err != nil {
		return Envelope{}, err
	}
	issuedAt = issuedAt.Round(0).UTC()
	expiresAt = expiresAt.Round(0).UTC()
	if !validTime(issuedAt) || !validTime(expiresAt) || !expiresAt.After(issuedAt) {
		return Envelope{}, fmt.Errorf("%w: invalid trust validity interval", ErrInvalid)
	}
	publicKey := privateKey.Public().(ed25519.PublicKey)
	keyID, err := KeyID(publicKey)
	if err != nil {
		return Envelope{}, err
	}
	envelope := Envelope{
		SchemaVersion: SchemaVersion,
		KeyID:         keyID,
		Scope:         scope,
		IssuedAt:      issuedAt,
		ExpiresAt:     expiresAt,
		Payload:       compact,
	}
	material, err := signingMaterial(envelope)
	if err != nil {
		return Envelope{}, err
	}
	envelope.Signature = base64.RawURLEncoding.EncodeToString(ed25519.Sign(privateKey, material))
	return envelope, nil
}

// EncodeEnvelope emits the single deterministic JSON wire representation.
func EncodeEnvelope(envelope Envelope) ([]byte, error) {
	if err := envelope.validateShape(); err != nil {
		return nil, err
	}
	encoded, err := json.Marshal(envelope, json.Deterministic(true))
	if err != nil {
		return nil, fmt.Errorf("encode trust envelope: %w", err)
	}
	if len(encoded) > MaxEnvelopeBytes {
		return nil, fmt.Errorf("%w: encoded envelope exceeds size limit", ErrInvalid)
	}
	return encoded, nil
}

// DecodeEnvelope strictly decodes one canonical wire envelope. Unknown or
// duplicate fields, alternate outer JSON encodings, and oversized payloads fail.
func DecodeEnvelope(encoded []byte) (Envelope, error) {
	if len(encoded) == 0 || len(encoded) > MaxEnvelopeBytes {
		return Envelope{}, fmt.Errorf("%w: envelope is empty or too large", ErrInvalid)
	}
	var envelope Envelope
	if err := protocol.DecodeStrict(encoded, &envelope, MaxEnvelopeBytes); err != nil {
		return Envelope{}, fmt.Errorf("decode trust envelope: %w", err)
	}
	canonical, err := EncodeEnvelope(envelope)
	if err != nil {
		return Envelope{}, err
	}
	if string(canonical) != string(encoded) {
		return Envelope{}, fmt.Errorf("%w: envelope JSON is not canonical", ErrInvalid)
	}
	return envelope, nil
}

// VerifyCurrent verifies the exact scope, signature, lifetime, and current
// validity. Use this API before any current mutation or secret retrieval.
func VerifyCurrent(envelope Envelope, expected Scope, keys Keyring, now time.Time, policy Policy) ([]byte, error) {
	if !validTime(now) || policy.MaxLifetime <= 0 || policy.ClockSkew < 0 {
		return nil, fmt.Errorf("%w: invalid verification policy", ErrInvalid)
	}
	if err := verifySignature(envelope, expected, keys, policy.MaxLifetime); err != nil {
		return nil, err
	}
	if envelope.IssuedAt.Sub(now) > policy.ClockSkew {
		return nil, ErrNotYetValid
	}
	if !now.Before(envelope.ExpiresAt) {
		return nil, ErrExpired
	}
	return bytesClone(envelope.Payload), nil
}

func verifySignature(envelope Envelope, expected Scope, keys Keyring, maximumLifetime time.Duration) error {
	if err := envelope.validateShape(); err != nil {
		return err
	}
	if err := expected.validate(); err != nil {
		return err
	}
	if envelope.Scope != expected {
		return ErrScopeMismatch
	}
	if !envelope.ExpiresAt.After(envelope.IssuedAt) || envelope.ExpiresAt.Sub(envelope.IssuedAt) > maximumLifetime {
		return fmt.Errorf("%w: invalid or excessive trust validity interval", ErrInvalid)
	}
	publicKey, exists := keys[envelope.KeyID]
	if !exists {
		return ErrUntrustedKey
	}
	keyID, err := KeyID(publicKey)
	if err != nil {
		return err
	}
	if keyID != envelope.KeyID {
		return ErrKeyMismatch
	}
	material, err := signingMaterial(envelope)
	if err != nil {
		return err
	}
	signature, err := decodeCanonicalSignature(envelope.Signature)
	if err != nil || !ed25519.Verify(publicKey, material, signature) {
		return ErrBadSignature
	}
	return nil
}

func (envelope Envelope) validateShape() error {
	if envelope.SchemaVersion != SchemaVersion || !domainRE.MatchString(envelope.Scope.Domain) || envelope.KeyID == "" || envelope.Signature == "" ||
		!canonicalTime(envelope.IssuedAt) || !canonicalTime(envelope.ExpiresAt) {
		return fmt.Errorf("%w: envelope header", ErrInvalid)
	}
	if _, err := decodeCanonicalSignature(envelope.Signature); err != nil {
		return err
	}
	if err := envelope.Scope.validate(); err != nil {
		return err
	}
	_, err := compactPayload(envelope.Payload)
	return err
}

func (scope Scope) validate() error {
	if !domainRE.MatchString(scope.Domain) {
		return fmt.Errorf("%w: scope domain", ErrInvalid)
	}
	if scope.Domain == DelegationDomain && scope == delegationScope() {
		return nil
	}
	if !entityid.Valid(scope.DeploymentID) || !cellRE.MatchString(scope.Cell) ||
		!tokenRE.MatchString(scope.Environment) || !tokenRE.MatchString(scope.Role) || !slotRE.MatchString(scope.Slot) {
		return fmt.Errorf("%w: incomplete or invalid scope", ErrInvalid)
	}
	return nil
}

func compactPayload(payload []byte) (jsontext.Value, error) {
	if len(payload) == 0 || len(payload) > MaxPayloadBytes || !utf8.Valid(payload) {
		return nil, fmt.Errorf("%w: payload is empty, invalid UTF-8, or too large", ErrInvalid)
	}
	value := jsontext.Value(payload).Clone()
	if err := value.Compact(jsontext.AllowDuplicateNames(false), jsontext.AllowInvalidUTF8(false)); err != nil {
		return nil, fmt.Errorf("%w: invalid payload JSON: %v", ErrInvalid, err)
	}
	if len(value) == 0 || value.Kind() != jsontext.Kind('{') {
		return nil, fmt.Errorf("%w: payload must be a JSON object", ErrInvalid)
	}
	return value, nil
}

func validatePayload(payload []byte) error {
	_, err := compactPayload(payload)
	return err
}

func signingMaterial(envelope Envelope) ([]byte, error) {
	payload, err := compactPayload(envelope.Payload)
	if err != nil {
		return nil, err
	}
	material := make([]byte, 0, len(signatureDomain)+256+sha256.Size)
	material = append(material, signatureDomain...)
	material = binary.BigEndian.AppendUint16(material, uint16(envelope.SchemaVersion))
	for _, field := range []string{
		envelope.KeyID, envelope.Scope.Domain, envelope.Scope.DeploymentID, envelope.Scope.Cell,
		envelope.Scope.Environment, envelope.Scope.Role, envelope.Scope.Slot,
		envelope.IssuedAt.Format(time.RFC3339Nano), envelope.ExpiresAt.Format(time.RFC3339Nano),
	} {
		if len(field) > 1<<16-1 {
			return nil, fmt.Errorf("%w: signed field exceeds limit", ErrInvalid)
		}
		material = binary.BigEndian.AppendUint16(material, uint16(len(field)))
		material = append(material, field...)
	}
	payloadDigest := sha256.Sum256(payload)
	material = append(material, payloadDigest[:]...)
	return material, nil
}

func validTime(value time.Time) bool {
	return !value.IsZero() && value.Year() >= 1 && value.Year() <= 9999
}

func canonicalTime(value time.Time) bool {
	return validTime(value) && value.Location() == time.UTC &&
		value.Format(time.RFC3339Nano) == value.UTC().Format(time.RFC3339Nano)
}

func decodeCanonicalSignature(encoded string) ([]byte, error) {
	signature, err := base64.RawURLEncoding.Strict().DecodeString(encoded)
	if err != nil || len(signature) != ed25519.SignatureSize || base64.RawURLEncoding.EncodeToString(signature) != encoded {
		return nil, ErrBadSignature
	}
	return signature, nil
}

func bytesClone(value []byte) []byte { return append([]byte(nil), value...) }

func ParseKeyring(publicKeys ...ed25519.PublicKey) (Keyring, error) {
	keyring := make(Keyring, len(publicKeys))
	for _, publicKey := range publicKeys {
		keyID, err := KeyID(publicKey)
		if err != nil {
			return nil, err
		}
		if _, exists := keyring[keyID]; exists {
			return nil, fmt.Errorf("%w: duplicate trusted root", ErrInvalid)
		}
		keyring[keyID] = append(ed25519.PublicKey(nil), publicKey...)
	}
	if len(keyring) == 0 {
		return nil, fmt.Errorf("%w: empty trusted root set", ErrInvalid)
	}
	return keyring, nil
}

func KeyID(publicKey ed25519.PublicKey) (string, error) {
	if len(publicKey) != ed25519.PublicKeySize {
		return "", fmt.Errorf("%w: expected an Ed25519 public key", ErrInvalidEnvelope)
	}
	digest := sha256.Sum256(publicKey)
	return "sha256:" + hex.EncodeToString(digest[:]), nil
}

// DecodeStrict decodes one bounded JSON value, rejecting duplicate names, invalid
// UTF-8, and unknown struct members. The Go 1.27 JSON v2 decoder rejects duplicate
// object names and invalid UTF-8 by default; RejectUnknownMembers closes the
// remaining permissive struct-decoding path.
func DecodeStrict(data []byte, destination any, maxBytes int) error {
	return decode(data, destination, maxBytes, true)
}

// DecodeTolerant is DecodeStrict for records a newer binary may have written:
// it skips members this binary does not know, so binary N-1 reads N's records.
// Duplicate names, invalid UTF-8 and the size limit still fail. A record's
// schema version names its breaking changes, and its reader checks it; a new
// member needs a safe zero value, since an older writer drops it.
func DecodeTolerant(data []byte, destination any, maxBytes int) error {
	return decode(data, destination, maxBytes, false)
}

func decode(data []byte, destination any, maxBytes int, rejectUnknown bool) error {
	if maxBytes == 0 {
		maxBytes = DefaultMaxJSONBytes
	}
	if maxBytes < 0 {
		return fmt.Errorf("%w: negative byte limit", ErrInvalidJSON)
	}
	if len(data) > maxBytes {
		return ErrJSONTooLarge
	}
	if !utf8.Valid(data) {
		return fmt.Errorf("%w: invalid UTF-8", ErrInvalidJSON)
	}
	if err := json.Unmarshal(data, destination,
		json.RejectUnknownMembers(rejectUnknown),
		jsontext.AllowDuplicateNames(false),
	); err != nil {
		return fmt.Errorf("decode protocol JSON: %w", err)
	}
	return nil
}

type Options struct {
	// Region is the canonical OCI region identifier from the catalog.
	Region string
	// Limits overrides DefaultLimits per service.
	Limits map[Service]Limit
	Retry  RetryOptions
}

// Factory hands out rate-limited, retrying OCI service clients for one region.
type Factory struct {
	provider common.ConfigurationProvider
	region   string
	limits   map[Service]Limit
	policy   common.RetryPolicy

	mu       sync.Mutex
	limiters map[Service]*rate.Limiter
	origin   *Factory
	regions  map[string]*Factory
}

// New builds a factory over an existing configuration provider. Region must be
// an OCI region in the catalog: the factory never addresses another region.
func New(provider common.ConfigurationProvider, options Options) (*Factory, error) {
	if provider == nil {
		return nil, errors.New("OCI client factory requires a configuration provider")
	}
	if !catalog.IsOCIRegion(options.Region) {
		return nil, fmt.Errorf("OCI client factory region %q is not in the region catalog", options.Region)
	}
	limits := make(map[Service]Limit, len(DefaultLimits))
	for service, limit := range DefaultLimits {
		limits[service] = limit
	}
	for service, limit := range options.Limits {
		if limit.PerSecond <= 0 || limit.Burst < 1 {
			return nil, fmt.Errorf("OCI client limit for %s must be positive", service)
		}
		limits[service] = limit
	}
	return &Factory{provider: provider, region: options.Region, limits: limits,
		policy: RetryPolicy(options.Retry), limiters: map[Service]*rate.Limiter{}}, nil
}

func (f *Factory) Region() string { return f.region }

// ForRegion preserves this factory's authentication and retry policy while
// selecting another catalog region, including the tenancy's home region.
func (f *Factory) ForRegion(region string) (*Factory, error) {
	if !catalog.IsOCIRegion(region) {
		return nil, fmt.Errorf("OCI region %q is not in the region catalog", region)
	}
	if f.origin != nil {
		return f.origin.ForRegion(region)
	}
	if region == f.region {
		return f, nil
	}
	f.mu.Lock()
	defer f.mu.Unlock()
	if sibling := f.regions[region]; sibling != nil {
		return sibling, nil
	}
	if f.regions == nil {
		f.regions = map[string]*Factory{}
	}
	sibling := &Factory{provider: f.provider, region: region, limits: f.limits,
		policy: f.policy, limiters: map[Service]*rate.Limiter{}, origin: f}
	f.regions[region] = sibling
	return sibling, nil
}

// Provider exposes the shared configuration provider for SDK helpers that need
// it directly (for example the Object Storage upload manager).
func (f *Factory) Provider() common.ConfigurationProvider { return f.provider }

// Limiter returns the shared token bucket for service.
func (f *Factory) Limiter(service Service) *rate.Limiter {
	f.mu.Lock()
	defer f.mu.Unlock()
	if limiter := f.limiters[service]; limiter != nil {
		return limiter
	}
	limit, ok := f.limits[service]
	if !ok {
		limit = defaultLimit
	}
	limiter := rate.NewLimiter(rate.Limit(limit.PerSecond), limit.Burst)
	f.limiters[service] = limiter
	return limiter
}

// Configure installs the shared limiter and retry policy on an SDK client and
// pins it to the factory region. An existing interceptor still runs, after the
// limiter admits the request. Each retry attempt passes through the limiter.
func (f *Factory) Configure(client *common.BaseClient, service Service) {
	limiter := f.Limiter(service)
	previous := client.Interceptor
	client.Interceptor = func(request *http.Request) error {
		ctx := request.Context()
		if ctx == nil {
			ctx = context.Background()
		}
		if err := limiter.Wait(ctx); err != nil {
			return fmt.Errorf("OCI %s rate limiter: %w", service, err)
		}
		if request.Method != http.MethodGet && request.Method != http.MethodHead && request.Method != http.MethodOptions {
			if guard, ok := ctx.Value(authorityKey{}).(func(context.Context) error); ok {
				if err := guard(ctx); err != nil {
					return fmt.Errorf("OCI %s write authority: %w", service, err)
				}
			}
		}
		if previous != nil {
			return previous(request)
		}
		return nil
	}
	policy := f.policy
	// Set only the retry policy: replacing the whole configuration would drop
	// a circuit breaker the SDK installed from OCI_SDK_DEFAULT_CIRCUITBREAKER_ENABLED
	// or its global setting.
	client.Configuration.RetryPolicy = &policy
	ConfigureReadCancellation(client)
}

func (f *Factory) Network() (core.VirtualNetworkClient, error) {
	client, err := core.NewVirtualNetworkClientWithConfigurationProvider(f.provider)
	if err != nil {
		return client, fmt.Errorf("create OCI network client: %w", err)
	}
	client.SetRegion(f.region)
	f.Configure(&client.BaseClient, ServiceNetwork)
	return client, nil
}

// ObjectStorage returns a rate-limited Object Storage client.
func (f *Factory) ObjectStorage() (objectstorage.ObjectStorageClient, error) {
	client, err := objectstorage.NewObjectStorageClientWithConfigurationProvider(f.provider)
	if err != nil {
		return client, fmt.Errorf("create OCI Object Storage client: %w", err)
	}
	client.SetRegion(f.region)
	f.Configure(&client.BaseClient, ServiceObjectStorage)
	client.HTTPClient = Instrument(client.HTTPClient, string(ServiceObjectStorage))
	return client, nil
}

func (f *Factory) Identity() (identity.IdentityClient, error) {
	client, err := identity.NewIdentityClientWithConfigurationProvider(f.provider)
	if err != nil {
		return client, fmt.Errorf("create OCI identity client: %w", err)
	}
	client.SetRegion(f.region)
	f.Configure(&client.BaseClient, ServiceIdentity)
	return client, nil
}

type instrumentedDispatcher struct {
	next    common.HTTPRequestDispatcher
	service string
	now     func() time.Time
}

// Instrument records one HTTP attempt without changing the dispatcher, limiter or retry policy.
func Instrument(next common.HTTPRequestDispatcher, service string) common.HTTPRequestDispatcher {
	if next == nil {
		next = http.DefaultClient
	}
	return &instrumentedDispatcher{next: next, service: service, now: time.Now}
}

func (dispatcher *instrumentedDispatcher) Do(request *http.Request) (*http.Response, error) {
	started := dispatcher.now()
	response, err := dispatcher.next.Do(request)
	elapsed := dispatcher.now().Sub(started)
	status := 0
	if response != nil {
		status = response.StatusCode
	}
	apiStats.record(dispatcher.service, operationTemplate(request), status, err != nil, elapsed)
	return response, err
}

// RequestContext keeps the SDK retry goroutine joined while the original context
// cancels the HTTP request and backoff. Use with ConfigureRequestCancellation.
func RequestContext(ctx context.Context) context.Context {
	if originalReadContext(ctx) != nil && ctx.Done() == nil {
		return ctx
	}
	return context.WithValue(context.WithoutCancel(ctx), readContextKey{}, ctx)
}

// ReadContext is RequestContext for existing read callers.
func ReadContext(ctx context.Context) context.Context { return RequestContext(ctx) }

type readContextKey struct{}

func originalReadContext(ctx context.Context) context.Context {
	original, _ := ctx.Value(readContextKey{}).(context.Context)
	return original
}

// ConfigureReadCancellation is retained for existing read callers.
func ConfigureReadCancellation(client *common.BaseClient) { ConfigureRequestCancellation(client) }

// ConfigureRequestCancellation must run after other interceptors are installed.
// It avoids the SDK Retry response race while preserving wire cancellation.
func ConfigureRequestCancellation(client *common.BaseClient) {
	if readCancellationConfigured(client.HTTPClient) {
		return
	}
	previous := client.Interceptor
	client.Interceptor = func(request *http.Request) error {
		if original := originalReadContext(request.Context()); original != nil {
			*request = *request.WithContext(context.WithValue(original, readContextKey{}, original))
		}
		if previous != nil {
			return previous(request)
		}
		return request.Context().Err()
	}
	client.HTTPClient = readDispatcher{next: client.HTTPClient}
}

func readCancellationConfigured(dispatcher common.HTTPRequestDispatcher) bool {
	switch dispatcher := dispatcher.(type) {
	case readDispatcher:
		return true
	case *instrumentedDispatcher:
		return readCancellationConfigured(dispatcher.next)
	default:
		return false
	}
}

type readDispatcher struct{ next common.HTTPRequestDispatcher }

type readTransportError struct {
	err error
	ctx context.Context
}

func (e *readTransportError) Error() string { return e.err.Error() }
func (e *readTransportError) Unwrap() error { return e.err }

func (d readDispatcher) Do(request *http.Request) (*http.Response, error) {
	var finish func(*http.Response, error, bool) error
	if request.Method != http.MethodGet && request.Method != http.MethodHead && request.Method != http.MethodOptions {
		deadline := new(admissionDeadline)
		*request = *request.WithContext(context.WithValue(request.Context(), admissionDeadlineKey{}, deadline))
		if begin, ok := request.Context().Value(wireAttemptKey{}).(func(*http.Request) (func(*http.Response, error, bool) error, error)); ok {
			if begin == nil {
				return nil, errors.New("OCI wire attempt journal is unavailable")
			}
			var err error
			finish, err = begin(request)
			if err != nil {
				return nil, fmt.Errorf("OCI wire attempt checkpoint: %w", err)
			}
			if finish == nil {
				return nil, errors.New("OCI wire attempt journal lacks outcome recorder")
			}
		}
		deny := func(err error) (*http.Response, error) {
			if finish != nil {
				err = errors.Join(err, finish(nil, err, false))
			}
			return nil, err
		}
		if finish != nil {
			if err := request.Context().Err(); err != nil {
				return deny(err)
			}
			// The durable begin may block; refresh the claim after that write.
			if guard, ok := request.Context().Value(authorityKey{}).(func(context.Context) error); ok {
				if guard == nil {
					return deny(errors.New("OCI wire authority is unavailable"))
				}
				if err := guard(request.Context()); err != nil {
					return deny(fmt.Errorf("OCI wire authority: %w", err))
				}
			}
		}
		if acquire, ok := request.Context().Value(admissionKey{}).(func(context.Context) (func(), error)); ok {
			if acquire == nil {
				return deny(errors.New("OCI write admission is unavailable"))
			}
			release, err := acquire(request.Context())
			if err != nil {
				return deny(fmt.Errorf("OCI write admission: %w", err))
			}
			if release == nil {
				return deny(errors.New("OCI write admission did not fence current authority"))
			}
			defer release()
		}
		if err := request.Context().Err(); err != nil {
			return deny(err)
		}
		if !deadline.until.IsZero() && !time.Now().Before(deadline.until) {
			return deny(errors.New("OCI current admission facts expired before dispatch"))
		}
	}
	if guard, ok := request.Context().Value(requestGuardKey{}).(func(context.Context) error); ok {
		var err error
		if guard == nil {
			err = errors.New("OCI request session is unavailable")
		} else {
			// Authorization may itself read OCI; those reads must not recurse
			// into the guard they are currently establishing.
			err = guard(context.WithValue(request.Context(), requestGuardKey{}, struct{}{}))
		}
		if err != nil {
			if finish != nil {
				err = errors.Join(err, finish(nil, err, false))
			}
			return nil, &readTransportError{err: err, ctx: request.Context()}
		}
	}
	// The final source guard may wait past a shorter retained admission cap.
	// Recheck it after that wait, immediately before the actual dispatch.
	finalErr := request.Context().Err()
	if deadline, ok := request.Context().Value(admissionDeadlineKey{}).(*admissionDeadline); ok && !deadline.until.IsZero() && !time.Now().Before(deadline.until) {
		finalErr = errors.Join(finalErr, errors.New("OCI original admission deadline expired during final source guard"))
	}
	if finalErr != nil {
		if finish != nil {
			finalErr = errors.Join(finalErr, finish(nil, finalErr, false))
		}
		return nil, &readTransportError{err: finalErr, ctx: request.Context()}
	}
	response, err := d.next.Do(request)
	if finish != nil {
		if recordErr := finish(response, err, true); recordErr != nil {
			if response != nil && response.Body != nil {
				_ = response.Body.Close()
			}
			err = errors.Join(err, fmt.Errorf("OCI wire outcome remains unknown: %w", recordErr))
		}
	}
	if original := originalReadContext(request.Context()); original != nil && err != nil {
		return response, &readTransportError{err: err, ctx: original}
	}
	return response, err
}

type RetryOptions struct {
	// MaxAttempts includes the first attempt. Zero selects the default.
	MaxAttempts uint
	// BaseDelay is the first backoff step before jitter. Zero selects the default.
	BaseDelay time.Duration
	// MaxDelay caps one backoff step, including a server Retry-After hint.
	MaxDelay time.Duration
	// Jitter returns a value in [0, 1). Nil uses math/rand/v2.
	Jitter func() float64
}

const (
	defaultMaxAttempts = 6
	defaultBaseDelay   = 500 * time.Millisecond
	defaultMaxDelay    = 30 * time.Second
)

func (o RetryOptions) normalized() RetryOptions {
	if o.MaxAttempts == 0 {
		o.MaxAttempts = defaultMaxAttempts
	}
	if o.BaseDelay <= 0 {
		o.BaseDelay = defaultBaseDelay
	}
	if o.MaxDelay <= 0 {
		o.MaxDelay = defaultMaxDelay
	}
	if o.MaxDelay < o.BaseDelay {
		o.MaxDelay = o.BaseDelay
	}
	if o.Jitter == nil {
		o.Jitter = rand.Float64
	}
	return o
}

// RetryPolicy returns the SDK retry policy shared by every TerraScale OCI
// caller. It never widens the effect of a mutation:
//
//   - 429 TooManyRequests is retried for every method, because OCI rejected
//     the request before acting on it.
//   - 5xx (except 501) and transport errors are retried only for reads (GET,
//     HEAD) and for POSTs that carry an opc-retry-token, which OCI
//     deduplicates. PUT and DELETE are not retried on 5xx because the first
//     attempt may have taken effect and callers classify that outcome
//     themselves (ETags, journals, exact-target teardown).
//
// Backoff is exponential with equal jitter and honors a Retry-After hint up to
// MaxDelay.
func RetryPolicy(options RetryOptions) common.RetryPolicy {
	options = options.normalized()
	return common.NewRetryPolicy(options.MaxAttempts, ShouldRetry, func(response common.OCIOperationResponse) time.Duration {
		return retryDelay(options, response)
	})
}

